quests[54731] = { id = 54731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance in All Things", description = "The confluence of energies around that vessel is truly disturbing. My skin crawls with the wrongness of it.\n\nWe have reached the limit of my ability to help you, {name}.\n\nGo to Ulfar, the High Thornspeaker. Arthur will carry you, if you wish it.\n\nOnly he knows enough about these ancient magics to undo the corruption that taints your materials.\n\nGo quickly. You do not want to hold that vessel longer than you must.", progress = "I sense a terrible power emanating from that vessel, {name}.", completion = "We will take what we have learned here and see what can be done about the rest of Drustvar.\n\nFor now, the Drust Vessel will be of use to you and Dorian.\n\nGive her my regards. She is an ally to the Thornspeakers, always.", objectives = "Speak to Ulfar and cleanse the Filled Drust Vessel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54732] = { id = 54732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drop It!", description = "You must be the person Dorian sent to collect the ore.\n\nI got a message a short while ago requesting a rather large shipment, which in itself is a feat given the state of this place. I was on my way to our storehouse when that... beast!... cornered me.\n\nIt took my keys. I can't get you that shipment without them. Find out where that mongrel took them and bring them back.\n\nLet it be known I wouldn't do this for anyone else.", progress = "<The Wicker Beast stares blankly at you.>", completion = "<The Wicker Beast sniffs the key.>", objectives = "Retrieve Chelsea Wright's keys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54733] = { id = 54733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make it Wright", description = "<Chelsea stares in horror at the Wicker Beast.>\n\nI don't know how this happened, or why... but I know this beast. \n\n<Chelsea hastily wipes away a tear.>\n\nI've unlocked our storage chest. Thank you. Thank you so much.\n\nTell Dorian she can call upon us at any time.", completion = "A note is affixed to the chest.\n\nIt reads:\n\n\"Dorian-\n\nThe mine has been in a bad way of late, but you will be glad to know that our standards remain as high as ever. \n\nGive Sal our best,\n\nChelsea W.\nWright & Co.\"", objectives = "Collect Dorian's ore shipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54734] = { id = 54734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons from Dorian", description = "<The elemental has a piece of parchment whipping around madly inside its tornado.>\n\nHHsssssss.\n\n<The elemental ejects the page into your face.>\n\nHHHHSSSSSSsssshh.", progress = "I see my little helper found you just fine.", completion = "I'm not fond of nobles sticking their nose in my work before it's finished. Deal with this.", objectives = "Return to Dorian Atwater at Port Fogtide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54735] = { id = 54735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Crew", description = "If Dorian really can build this ship before the day is out, we need to find a crew for the new vessel.\n\nThis crew should represent the best of Kul Tiran society, the highest naval prowess, and the faith of our people as we present this gift to Anduin.\n\nI have a captain in mind, but you'll want to speak to him yourself. I will let him decide who else he wants aboard.\n\nSeek out my brother, Tandred Proudmoore, in Boralus. He will help you fill out the ranks from there.", progress = "Have you found a suitable crew?", completion = "This is a fine group you've assembled. Very well done.", objectives = "Recruit a crew for the new vessel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54736] = { id = 54736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", objectives = "Desecrate the Alliance's Tiragarde Sound bonfire!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
