quests[54906] = { id = 54906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward" }
quests[54913] = { id = 54913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spark of Genius", description = "{name}, I have wondrous news!\n\nA recent energy signature tripped several detection relays I installed after that unfortunate incident with Sargeras.\n\nI require further data to know for certain, but initial diagnostics suggest that these energies are coming from Hati! We might still be able to save him!\n\nHati's spirit is still bound to your own, so I'll need your help. Meet me at my library in the Storm Peaks right away!", completion = "Our scientific team simply would not be complete without Bronzebeard here.\n\nLet's begin!", objectives = "Meet Mimiron at the Inventor's Library in the Storm Peaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54915] = { id = 54915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telemetry Online", description = "When Titanstrike's power was expended in Silithus, Hati's essence managed to sever itself from the Thunderspark just in time to avoid destruction.\n\nThe only problem is that his essence was then scattered across Azeroth, and we don't know where.\n\nNow that we've locked onto his energy signature, we should be able to triangulate Hati's position!", progress = "Everything is possible with science!", completion = "Now that we've located Hati's essence, we can move to phase two of my glorious plan!", objectives = "Assist Mimiron in locating Hati's essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54916] = { id = 54916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Huntsman's Creed", description = "Through the glorious wonder of science, I have managed to keep the Thunderspark powered precisely for this purpose.\n\nAll you need to do is get to the Temple of Storms and absorb Hati's essence into it. Just... kind of point it in his general direction.\n\nOh, and do keep in mind that this is only one part of Hati. You may run into a few... technical difficulties before he's subdued enough for the absorption protocol.", completion = "One down, one tae go!", objectives = "Absorb Hati's essence into the Thunderspark at the Temple of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54917] = { id = 54917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paid in Blood", description = "If Mimiron's fancy gadgets be right, then the other half o' Hati is near the wound in Silithus.\n\nWe'll have tae move quickly. Even with part o' his essence contained, I can feel him fadin' away fast!\n\n'Tis a long trip, <lad/lass>. Let's get movin'!", progress = "Yes?", completion = "No time to chat. I need you at my lab in Ulduar at once!", objectives = "Absorb Hati's essence into the Thunderspark at the Wound in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54918] = { id = 54918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spark of Imagination", description = "I've diverted all non-essential power to prepare for Hati's reformation, so I cannot teleport you to Ulduar from here.\n\nBe extremely careful with the Thunderspark on your way. It is charged with highly volatile energy. One wrong bump could lead to serious complications!", completion = "Quickly, now! We may not have much time!", objectives = "Use the Teleportation Pad outside Ulduar to rendezvous with Mimiron in his workshop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54919] = { id = 54919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonds of Thunder", description = "While you infused Hati's essence into the Thunderspark, I have concocted a flawless plan the likes of which the scientific world has never seen!\n\nI'll spare you the technical details. Just follow my instructions and Hati will be back in one piece in no time at all!\n\n...Or we will all explode. But risks must be taken in the pursuit of knowledge and the well-being of our furry companions, wouldn't you agree?", progress = "I know how long you have been waiting for this day, {name}.", completion = "I have never seen a creature so excited!", objectives = "Reform Hati.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54920] = { id = 54920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Homeward Bound", description = "The reformation procedure went positively flawlessly! Most excellent results indeed--and plenty of data to analyze!\n\nI'm not sure what it is Thorim has to show you, but I suggest you get to the Temple of Storms right away. He gets a bit destructive when he's kept waiting.\n\nTake my teleporter pad directly out of Ulduar. I'm afraid the normal route to the entrance is... inoperable at the moment.", completion = "You brought the Thunderspark with you, I trust. We shall need it!", objectives = "Meet Thorim at the Temple of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54922] = { id = 54922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nuts and Bolts of It", description = "I started working on the leg gearing. Most the gearing around here is built from spare parts we find in the scrap heaps. \n\nWe're going to need a lot of spare parts to fix this thing. See what you can find.", progress = "Bring me those spare parts!", completion = "Nice work, this will help a lot.", objectives = "Collect 1000 spare parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54925] = { id = 54925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heresy!", description = "My own prelates are among them that revolted against Talanji. This is an unspeakable heresy.\n\n I will not tolerate it! \n\n<She gestures to the prelate before her with her spear.>\n\nThis one has wisely told me who is to blame. My second, Kaj'ra.\n\nI would have heard her, had she used any other means to make her concerns known. Now she must be disposed of.\n\nYou will find her in de Terrace of de Chosen.", progress = "Death is too good for that heretic.", completion = "<High Prelate Rata spits on the ground.>\n\nBwonsamdi keep her.", objectives = "Slay Prelate Kaj'ra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54929] = { id = 54929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready to Rumble", description = "We're going to need a new Sixteen-Servo-Actuator if we're going to fix the controls on this thing.\n\nBondo's gang at the yard probably has one, but they usually aren't too helpful.\n\nTalk to Bondo, see if you can get us one.", progress = "Did you head over to the yard yet?", completion = "I really didn't think Bondo would give us one of these!", objectives = "Acquire a Sixteen-Servo-Actuator from Bondo Bigblock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54930] = { id = 54930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanical Liberation", description = "Since you successfully interrupted my nap, my defenses are obviously lacking to say the least. \n\nThat's because the sethrak, in addition to stealing my gadgets and gizmos, stole my mechs! Those morons don't even have the keys!\n\n<Gryzix laughs>\n\nHere, take my keys and get my mechs back.", completion = "Ah, yes. My mechs!\n\nA little muscle goes a long way it seems...", objectives = "Free Mecha-Golems in the Scalefang Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54933] = { id = 54933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freeing the Light", description = "Ah... you are not in league with the ogres. Please, you must aid me.\n\nI have been bound against my will by dark magic. I ask only that you free me.\n\nTake a piece of my light. Use it to dispel the shadow energies that are keeping me captive.", progress = "Use my light to dispel the necrotic energies binding me to this place.", completion = "You have my thanks, {name}. I must leave this world, but I wish you luck. \n\nTake my blessing. May it aid you against these monsters.", objectives = "Use the Lightspawn's light to dispel nearby shadow energy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54938] = { id = 54938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brother's Help", description = "We're gonna need all the help we can get te save the planet.\n\nI've got an idea.\n\nMeet me in Nazmir, outside the Heart of Darkness. Together, we'll seek guidance from someone who may be able to help.", completion = "Can ye please talk some sense into Brann fer me?", objectives = "Travel to Nazmir and meet Magni outside Uldir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54939] = { id = 54939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stubborn as a Bronzebeard", description = "It's kind o' Brann tae offer, but his flying machine would drop like a rock with me aboard. Best if it carry just the two of ye.\n\nBrann will fly ye down to Uldir. I'll find me own way and meet ye inside.", completion = "Ah good, I see ye've arrived in one piece. Now let's see if MOTHER can lend us a hand.", objectives = "Take Brann's Flying Machine to Uldir.\n\nIf you get lost, use the teleporter pad outside the entrance to Uldir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54940] = { id = 54940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necessity is the MOTHER", description = "I may be Azeroth's speaker, but Brann's the expert on titan archaeology. If he says that MOTHER can help us save Azeroth, then I'm more than willing tae place my faith in her.\n\nCome, champion. Let's hear what guidance she has tae offer.", progress = "I'll never understand exactly how all these machines work. That's what Brann does!", completion = "It's just as I feared. We don't have much time, champion. This may be our only hope.", objectives = "Take Magni to meet MOTHER and activate Waygate Consoles", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54941] = { id = 54941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting The Strand", description = "It has been a long time since we have heard from our scouts at the outpost.\n\nThey may have been cut off from us due to the naga attack. I need to check in with them and get an update on the movements of the naga forces.\n\nYou should come with me, this will be a good opportunity for you to meet more of the clan and get a closer look at our operation.", objectives = "Locate the Ankoan scouts at the Ashen Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54943] = { id = 54943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Ranger's Pupil", description = "Thank the abyss you're here, Huntmaster {name}!\n\nI'm concerned about Dark Ranger Velonara. We have become good friends during our time together in the Trueshot Lodge, and I fear she is in peril.\n\nShe's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about all this. Could you check on her safety?", sourceObjective = "Find Dark Ranger Velonara in Tirisfal Glades.", sourceObjectiveStatus = "unverified-source-field" }
quests[54944] = { id = 54944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Ranger's Pupil", description = "Thank the abyss you're here, fellow hunter!\n\nI'm concerned about Dark Ranger Velonara, who frequents the Trueshot Lodge. Velonara is a good friend, and I fear she is in peril.\n\nShe's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about all this. Would you be willing to check on her safety?", sourceObjective = "Find Dark Ranger Velonara in Tirisfal Glades.", sourceObjectiveStatus = "unverified-source-field" }
quests[54945] = { id = 54945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Get It Started", description = "I theorize this to be a communication relay. It is non-operational, but gnomish ingenuity and your strong back shall soon solve that problem!\n\nI need you to help get this device functional.", progress = "We need this device repaired.", completion = "This is a monumental success. The device appears to be fully operational!", objectives = "Repair the device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54946] = { id = 54946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Gila", description = "I was quite fortunate that King Mechagon found me worthy!  \n\nI will send my assistant Gila Crosswires ahead to Boralus to gather a new team. Meet up with her and help out as you can.\n\nI will join both of you shortly.", completion = "The Tinkmaster has entrusted me with this task, so let's not mess it up!", objectives = "Meet up with Gila Crosswires in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54947] = { id = 54947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Team", description = "I've determined the single attribute that is most important for a team member to survive an expedition to Mechagon.  \n\nThat attribute is...being a gnome!\n\nGather these gnomes and meet Tinkmaster Overspark and myself at the departure point.", completion = "Everyone and everything is packed up and ready to go.", objectives = "Gather the team members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54949] = { id = 54949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Mouths To Feed", description = "The naga attack us relentlessly, so there is precious little time to hunt for food and supplies.\n\nYou have brought many soldiers to our camp, so we must hunt while we have the chance or we will soon run out of food.", progress = "The meat from this hunt shall nourish our bones.", completion = "There is nothing like fresh meat to strengthen the bones and lift the spirits of weary soldiers!", objectives = "Collect 30 Snapshell Flesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54951] = { id = 54951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency First Aid", description = "We have to patch everyone up before we can begin the search for the missing expedition.\n\nTake this first aid kit and tend to the wounded.", progress = "Walk up to Austin, Bjorn, and Kee-La and use the first aid kit to heal them. Do not move while using it.", completion = "We're ready to move. Let's find that missing expedition.", objectives = "Use a First Aid Kit on Austin Huxworth, Bjorn Stouthands, and Kee-la.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54952] = { id = 54952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Lost Expedition", description = "Captain Garrick went ahead to find survivors. It looks like she lit a fire.\n\nMeet her up ahead to see what she found. \n\nI'll look further within the island for survivors... and the source of the magic that attacked us.", completion = "The others... taken... \n\nNeed... food...", objectives = "Search the nearby camp for expedition survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54958] = { id = 54958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ships in the Night", description = "Sylvanas has gone too far this time. We may be at war with the Alliance, but there are certain lines we cannot cross.\n\nI must right this situation, but I need your assistance. Derek Proudmoore is being held on the Swift Vengeance, which is moored in the harbor here for supplies. \n\nWe must take him and bring him back to his family. Are you with me?", progress = "There's no time to waste.", completion = "Proudmoore is here, but this cage may prove problematic.\n\nI don't think we're going to be able to brute force this lock.", objectives = "Take the boat to the Swift Vengeance and find Derek Proudmoore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54959] = { id = 54959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Lock and Keys", description = "Three keys? It seems Sylvanas didn't trust any one member of this crew to have access to Proudmoore.\n\nWe won't be able to rescue Derek Proudmoore if we can't get his cage open. \n\nWe'll need to keep an eye out for keys while we clear the ship.", progress = "This will all be for nothing if we can't open that lock...", completion = "We've done it!\n\nI was worried I would have to try to bend the cage bars apart.", objectives = "Collect the Captain's Key, Apothecary's Key, and Navigator's Key on the Swift Vengeance, then use them to open the Reinforced Cage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54960] = { id = 54960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bitter Reunion", description = "We've done it! Zelling will guide the ship to Theramore, and we can put an end to this foul business once and for all.\n\nSpeak to Zelling when you are ready to leave, and we will set sail.", progress = "We sail at your command, {class}.", completion = "Thank you for your help, {class}. \n\nI must return home, but Zelling has a plan to hide our actions from Sylvanas' eyes.\n\nThe Banshee Queen must not learn of what transpired here, for it would put far more lives at risk than our own.", objectives = "Speak to Thomas Zelling to set sail to Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54961] = { id = 54961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righting Wrongs", description = "Champion! I come with an urgent request from Baine Bloodhoof. He asks that you meet him at Plunder Harbor to help him with a... sensitive situation.\n\nYou must tell no one of this request, {class}. \n\nAncestors watch over you.", progress = "I see you've received my message.", completion = "You're here.\n\nGood, now we can proceed.", objectives = "Meet with Baine Bloodhoof at Plunder Harbor in Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54964] = { id = 54964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A One-Way Ticket to the Heart", description = "These titan facilities never cease tae amaze me. I can only imagine how many of their secrets Brann has yet tae uncover.\n\nI just hope that one o' them holds the answer tae saving Azeroth.\n\nIt's time tae bring MOTHER tae the Chamber of Heart. Be prepared for anythin', champion. Ye can never be quite sure what will happen when ye activate a titan machine.", completion = "That was close! But we made it back tae the Chamber of Heart. Now tae see if MOTHER can find a way to heal Azeroth.\n\nThank ye, {name}.", objectives = "Evacuate MOTHER from Uldir", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54965] = { id = 54965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chopped Bots", description = "Chopping up bots is my business. Any bots you bring to my scrapper will be broken up into useful parts. It's a win for both of us!\n\nUse the Bot-Energizer to bring me dead bots, and we'll break them into spare parts.", progress = "Re-animate dead bots and bring them to me!", completion = "I love those spare parts! You're can grind up bots here anytime you want!", objectives = "12 Re-animated bots delivered to Bolten Springspark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54969] = { id = 54969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descent", progress = "Never give up.", completion = "Thank you for giving me your trust.", objectives = "Jump off the falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54972] = { id = 54972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Way Home", description = "We are only alive thanks to the ankoan and Azshara's desire to toy with us.\n\nWe will learn more of Okani's people in the times ahead, I am sure.\n\nFor now, we must establish a portal home. While Azshara is blocking our traditional methods of magical travel, I can sense a powerful convergence of energies nearby.\n\nI believe we can use it to open a way home.", completion = "We are exceptionally lucky to have met the ankoan. Perhaps things are not as dire as they seem.", objectives = "Help Jaina open a portal to Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54975] = { id = 54975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brief Respite", description = "We have much to do, {name}. However, we are all weary and require rest. Decisions made while fatigued are almost always the wrong ones to make.\n\nThe Ankoan have offered their home to us, yet they are barely holding on themselves. We should do what we can to support them while we think about our next move.\n\nSee what you can do to aid their hunting parties, it may be the only way we survive in this place.", completion = "Good work. Your efforts have helped us establish some trust with our new allies and gained some much-needed combat experience in this strange place.\n\nThey have entrusted us with this item, I sense incredibly power within. It is clearly attuned to the Heart of Azeroth, you should take it. Hopefully it is of use to us.", objectives = "Support your allies in Nazjatar by getting one to rank 3.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54976] = { id = 54976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow of Gilneas", description = "Champion of Gilneas!\n\nI have a letter for you from Princess Tess Greymane. She requests your presence in Stormwind Keep.", completion = "You have arrived just in time, {name}.", objectives = "Meet with Tess Greymane at Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54977] = { id = 54977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Duskwood", description = "There is a night elf I met in Teldrassil, Vassandra Stormclaw, who may be able to teach Tess without resorting to such an extreme measure. She is the one who originally helped our people with their affliction.\n\nVassandra is currently in Duskwood, assisting the residents of Raven Hill with their attempts to cure the feral worgen in the area. If anyone knows about the curse, it is her.\n\nAs a more personal request, do not let my daughter do anything too rash. She takes after her father in that way.", completion = "Is there something you need, {class}?", objectives = "Speak with Vassandra Stormclaw in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54978] = { id = 54978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "We've received numerous reports of the Horde overwhelming our forces within both Kul Tiras and Zandalar. \n\nBrute forcing the Alliance with sheer numbers is an age-old tactic of the Horde, but we can't allow them to get the upper hand.\n\nVenture forth throughout and thin their numbers the best you can. I recommend bringing reinforcements.", completion = "Great work, {class}.", objectives = "Slay 25 Level 50+ Horde anywhere within Kul Tiras, Zandalar, Nazjatar, Uldum or Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54979] = { id = 54979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "It appears we've allowed the Alliance forces to fester. If these reports are correct, they're outnumbering us in nearly every bastion we hold. \n\nArm yourself, grab a few of your most trusted allies and put them into the ground, {class}!", objectives = "Slay 25 Level 50+ Alliance anywhere within Kul Tiras, Zandalar, Nazjatar, Uldum or Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54980] = { id = 54980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bane of the Nightbane", description = "Princess Greymane has informed me of the situation and I do have an idea of how to help.\n\nBut first, a favor for a favor. The residents of Duskwood have been plagued recently by a particularly ferocious member of the Nightbane pack that they call 'Bloodeyes'. Take Master Harris's sedative and bring the worgen back to me alive. She will be a perfect subject to test cures on.", progress = "If we can cure even the most feral of {race}, then the curse will mean nothing to us.", completion = "I thank you for your help. Tess has yet to return from her task.", objectives = "Subdue Bloodeyes and return with her to Raven Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54981] = { id = 54981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cry to the Moon", description = "Duskwood has a direct connection to the Emerald Dream. Through this connection, I may be able to call forth the Ancient Goldrinn. He will be able to give the princess a taste of the curse she so dangerously chases.\n\nA rare bloom grows on the east side of the woods, gather its bloom and meet me in Twilight Grove. It will help me with this ritual.", progress = "Such flowers have been known to attract wolves, but I doubt you will have a problem with that.", completion = "Perfect. This should help lure the great wolf out of hiding.", objectives = "Gather a bloom of Elune's Grace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54982] = { id = 54982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirit of the Hunter", description = "The other thing I may need for this ritual are the fangs of a wolf.\n\nThere is a pack that has newly settled in around Manor Mistmantle. Bring me their fangs. I will await your return at Twilight Grove.", progress = "Did you claim your trophy?", completion = "The Scythe of Elune was formed using the fang of Goldrinn. This ritual attempts to echo just a small bit of that power.", objectives = "Retrieve the fangs from Mistfang wolves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54983] = { id = 54983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking a Dreamer", description = "This should be all I need to call upon the Ancient.\n\nSome unwanted visitors may answer the call first. Protect me as I perform the ritual!", completion = "The Dream can be a perilous place. Do you wish to join her?", objectives = "Defend Vassandra Stormclaw as she summons Goldrinn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54984] = { id = 54984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Sleeping Wolves Lie", description = "Tess's essence now wanders a section of the Emerald Dream I have twisted into her thoughts. And I have given her my gift, but she could still use a guide.\n\nEnter the Dream through the portal behind me. It will place you near where she sleeps. See if you can help show her how rage may blind a mortal.", completion = "I... I need to talk with my father.", objectives = "Enter the Dream Portal and guide Tess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54986] = { id = 54986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision of N'zoth Reward" }
quests[54990] = { id = 54990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Guard", description = "I need to speak with my parents again. I think my father and I have a bit to discuss.\n\nMeet me back at Stormwind Keep. I would like to thank you in a more formal manner.", progress = "Yes?", completion = "Consider it more of an honorary title. I hope I never see the day where I am forced to rely on it.", objectives = "Meet Tess Greymane at Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54992] = { id = 54992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Start of Something Bigger", description = "We have coordinates locked into the gyrocopters. You and Captain Winklespring will fly the lead. If we run into any trouble, Tinkmaster Overspark wants the most experienced pilots out front.\n\nBoard whenever you are ready to go.", completion = "It appears King Mechagon mistook us for enemies.", objectives = "Board the Expedition Gyrocopter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54995] = { id = 54995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Savage Path Through Time", description = "The brutal star shines upon the land, threatening to trample underfoot all who stand in its path. This star is many things: primal, fierce, and noble. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54996] = { id = 54996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remembrance", description = "You may remember the day Thunder Bluff was attacked. It was your efforts and your guide who saved us.\n\nNow we take time to honor our ancestors and give thanks for the path they have set for us.\n\nBring this offering to the cliffs overlooking Thunder Bluff and give thanks to your guide and all our ancestors.\n\nA simple gesture to commemorate our past. This is our way.", completion = "On this day we remember and give thanks to the ones who have come before us. May the Earth Mother guide you.", objectives = "Deliver the offering to your spirit guide on the cliffs overlooking Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54997] = { id = 54997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead in the Water", description = "Once Proudmoore is freed, we will need to commandeer this ship to transport him to Theramore, where his sister awaits us.  \n\nZelling's magic can guide the ship there, but first we'll need to take care of the crew.", completion = "The ship is clear. \n\nI will signal Zelling to join us.", objectives = "Defeat 6 crew members aboard the Swift Vengeance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54999] = { id = 54999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under False Colors", description = "If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. I will take the ship near Chandlery Wharf, which has recently been taken by Irontide pirates. There, I will leave it under the guise of a pirate raid gone wrong.\n\nYour task will be to ensure that Sylvanas' forces find this ship.\n\nYou must report to Nathanos that you spotted a stolen Forsaken vessel in that area.  You have no connection to Derek Proudmoore, so it should raise no suspicions.", progress = "Out with it, {class}.", completion = "A pirate crew dared abscond with a vessel of the Dark Lady's fleet? Clearly, they must be made to pay. I will dispatch our forces to search the area for the stolen ship. \n\nThank you for this information, {name}. I will personally inform the Dark Lady of your... involvement.", objectives = "Start the mission \"Casting the Bait\" then report to Nathanos Blightcaller aboard the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55002] = { id = 55002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder at the Brawlpub", description = "The Brawlpub quartermaster lies dead in front of you. He was murdered in broad daylight!\n\nHe must have been assassinated while someone was fighting in the arena. Maybe even during one of your fights.\n\nPerhaps there are some clues nearby as to who might have killed him.", completion = "So, you took it upon yourself to investigate the murder? Interesting...\n\n<Commander Daalo jots something down, looks up at you, and then finishes writing his notes.>", objectives = "Investigate the scene of the crime.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55003] = { id = 55003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put Up Your Dukes", description = "You know what?\n\n<The commander puts his notebook away.>\n\nI COULD use a good {class} on my investigations team. We've had some personnel issues lately and, frankly, I can use all the help I can get.\n\nBut first: why don't you go hop into the arena for a few fights so I can get a good look at your skills?", completion = "While you were fighting, I took the liberty of looking into your background a bit, {name}. Quite impressive, I must say.\n\nI apologize for my earlier suspicions. Welcome to the team.", objectives = "Win any 3 fights in Bizmo's Brawlpub.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55004] = { id = 55004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercover Agent: Ann Dennyson", description = "Lord Winifred Browne is one of our primary suspects in this case. Browne is an infamously aggressive speculator, and has a list of debts a mile long.\n\nHe may be in need of money, which is consistent with the evidence you found earlier.\n\nMy associate Ann has taken point on the case. I'd like you to assist her. I think you'll work well together.", completion = "{name}? Ann. Pleased to make your acquaintance.\n\nLord Browne is over there, with the ridiculous hat on him.\n\nNo, no... don't just stare right at him! We're undercover, bonehead.", objectives = "Report to Ann Dennyson in Bizmo's Brawlpub.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55005] = { id = 55005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Financial Participation Incentive", description = "I see Lord Browne running some sort of game over there. Getting people to guess the fight's winner in exchange for Brawler's Gold.\n\nSee if you can figure out how his game works. If you win enough money from him, he might start talking...", progress = "Lookin' to make some gold, old chap?", completion = "Say, {name}, was it? You're not half bad at this! You'll put me in the poor house if you keep this up!", objectives = "Win 100 Brawler's Gold from Lord Winifred Browne's guessing game.\n\nIf the game is not currently active, anyone can activate it by purchasing a High Roller's Contract from Ulaani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55006] = { id = 55006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for Your Old Chum Winifred", description = "A moment of your time, <good sir/madam>.\n\nIt's about all that money you won from me. Interestingly enough, that may have been slightly more money than I actually have, and now it would appear that some very powerful people want to break my elbows and my knees.\n\nI cannot pay them!  Ha ha!\n\nAll I need to get back above water is for you to lose your next fight. Flop like a fish, as they say. Please.", progress = "You must help me! Their threats were quite descriptive, and slightly scatological!", completion = "Many thanks, {name}.", objectives = "Lose a fight in Bizmo's Brawlpub.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55007] = { id = 55007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Browne's Debts", description = "I've always said that I'm not too proud to  to set a wrong right. And you know what's wrong? I'm out of money!\n\nOnly one person's won more gold from me than you have, and his name's Lord Sylysthrel. Quite the scoundrel, that one. I believe he was cheating.\n\nIt sure would be nice if I could get that gold back...", progress = "Once I get back the gold I lost, then I can REALLY start gambling!", completion = "<Lord Browne stares, misty-eyed, at the huge pile of money.>\n\nI do love gold. There is nothing I wouldn't do to get my hands on gold. Indeed, I would stoop quite low to pick up a single piece of gold. And I have in the past!", objectives = "Obtain a Huge Pile of Legitimately-Earned Brawler's Gold from Lord Sylysthrel.\n\nYou can challenge Lord Sylysthrel by purchasing his Challenge Card from Card Trader Leila.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55008] = { id = 55008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evidence Packet: Lord Winifred Browne", description = "I heard everything. That guy sure does talk loudly about his crimes and debts, doesn't he?\n\nIt sounds like we have enough to bring him in for questioning. I've put together a packet of evidence for Commander Daalo to review.\n\nGood job out there.", progress = "Find anything on Browne?", completion = "<Commander Daalo looks over the evidence.>\n\nThis is more than enough to get a warrant. Excellent work, {name}. But your job's not over yet.", objectives = "Bring the Evidence Packet to Commander Daalo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55009] = { id = 55009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercover Agent: Saralara Fizzlesprang", description = "I believe you've met one of my other agents: Saralara Fizzlesprang. She's investigating our second suspect: Shadowmaster O'Flannerty.\n\nYou'll find Saralara near the scene of the crime.", completion = "{name}? Saralara Fizzlesprang. Nice to meet you. Again.\n\nO'Flannerty's back over there, to my left. You go take point, I'll hang back and jump in if things get ugly.", objectives = "Speak with Saralara Fizzlesprang at Bizmo's Brawlpub.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55010] = { id = 55010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Splinters", description = "<O'Flannerty mumbles to himself.>\n\nAchh, what a mess... it's getting hungry again. Where am I going to find enough souls to feed it? Ohh... if only I could get my hands on some of those brawler's purses...\n\n<He notices you.>\n\nOh! Ahoy there! Pay no attention to the mindless babbling of an innocent warlock. Nothing suspicious going on here!", progress = "Oh dear, oh dear... must not let it get too hungry...", completion = "These... these might help! They'll help me with... my problem that I have. That I can't tell you about.", objectives = "Search inside Brawler's Purses for something \"soul\"-related.\n\nBrawler's Purses are awarded to victors in Bizmo's Brawlpub. Some types of purses may be more lucrative than others.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55011] = { id = 55011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Soul Splinters", description = "<O'Flannerty mutters to himself again:>\n\nWill these be big enough, though? It gets SO hungry for souls, and when it doesn't get enough, it gets angry, and we definitely don't want to trigger a  in the middle of Stormwind. Oh dear, oh dear...\n\n<He notices you lingering.>\n\nOh! The {race} is still here! Heh heh. Never mind me! Nothing evil going on here!!", progress = "<O'Flannerty looks around the arena in a panic.>\n\nWhere can I find more souls? Maybe the quartermaster sells some? Oh, right, he's dead. Hmm...", completion = "These... are... PERFECT!\n\nNow if you'll please give me some privacy, I have some completely harmless |cFF0000FFshadow magic|r to perform. Goodbye!", objectives = "Obtain 3 Super Soul Splinters from Rumbler's Purses, which are rewarded from winning rumbles.\n\nRumbles are large group fights that pit all players in Bizmo's Brawlpub queue against a challenging enemy. Anyone can start a rumble by purchasing a Rumble Card from Ulaani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55012] = { id = 55012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cause for Concern", description = "Shadowmaster O'Flannerty's behavior was unusual.\n\nHis repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation.\n\nYou should report back to Saralara Fizzlesprang.", completion = "<She listens to your report.>\n\nHmm. Yes. I think I know what's going on. It looks like we're going to have to solve this problem with science.", objectives = "Report to Saralara Fizzlesprang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55013] = { id = 55013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Precious 13-Tooth Gogglegear", description = "We're going to have to invent something. Something capable of seeing into alternate dimensions. Something explosive that you strap directly onto your eyes.\n\nThat's right, I'm talking about goggles.\n\nI already have all the goggle parts except for one: a 13-tooth gear. They're nearly impossible to find, but I KNOW that the G.G. Engineering boys have one, and Card Trader Leila has their challenge card.", progress = "Are you ready to goggle up?", completion = "<Saralara forcefully smashes the gear into a pair of goggles.>\n\nThere! Goggles done.", objectives = "Obtain a 13-Tooth Gogglegear from G.G. Engineering. You can purchase their challenge card from Card Trader Leila.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55014] = { id = 55014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fizzlesprang Goggle Experiment", description = "Okay, before we start, I've got a few rules:\n\nFirst, these goggles will only work at close range. We're looking for something INSIDE the arena, so you'll have to be inside the arena to use them.\n\nSecond rule: if you feel something starting to explode, try to blink real hard.\n\nLastly, remember, we're looking for an evil shadow monster. You don't need to kill it, we just need you to see it so we can report it as evidence.\n\nAlright, go get in that arena and try them out!", completion = "<Saralara listens intently as you recount the horror that you witnessed within the arena.>", objectives = "Put on Saralara's Goggles while fighting in Bizmo's Brawlpub and look for evidence against Shadowmaster O'Flannerty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55015] = { id = 55015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evidence Packet: Shadowmaster O'Flannerty", description = "Sounds like we've found our perp, {name}. This guy's sketchy, desperate, and his shadow magic is consistent with that shadowy scroll you found earlier.\n\nBring this packet to Daalo, and we can bring him in. Good work out there!", progress = "Any news on O'Flannerty?", completion = "<The commander looks over the notes.>\n\nWow. It's worse than I thought. We'd better bring him in soon, because this guy's a nut job.", objectives = "Bring the Evidence Packet to Commander Daalo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55016] = { id = 55016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercover Agent: Silent Jussho", description = "I've got one more suspect I'm investigating: Grant Lazarby. He's a wealthy worgen death knight socialite who spends most of his time spectating the arena from the VIP area.\n\nI've got my best agent on the case: Silent Jussho. Check in with him to see how his report is coming along.", completion = "Shh! Don't blow my cover.\n\nHe's over there. You go talk to him. I'll watch.", objectives = "Report to Silent Jussho in the Brawlpub VIP Lounge.\n\nTo enter the VIP Lounge, you must either be Rank 6 in Bizmo's Brawlpub, or someone must purchase a VIP Room Rental Form from Ulaani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55017] = { id = 55017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flaunt It If You Got It", description = "Sigh... so dull...\n\nOh, it's you! {name}, was it? I've seen a few of your fights. They're slightly less tedious than the standard humdrum bloodsport this arena has been producing lately.\n\nLet's spice things up a bit. Maybe buy some expensive drinks for ourselves? Buy a round of the cheap stuff for the riffraff below? Maybe even toss a few amberseed buns at the combatants?", completion = "Ha hah! I KNEW you knew how to party.\n\nI'm in a much better mood now. This is the most entertained I've been since that quartermaster was murdered!", objectives = "Drink a bottle of Moneybrau, purchase a round of drinks at the bar in Bizmo's Brawlpub, and hit a fighting player with an Amberseed Bun while standing in the VIP Lounge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55018] = { id = 55018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simply Dying of Boredom", description = "Up until now, I've been dying of boredom up here. I think maybe we need some new blood here in the arena. Bizmo can be so stingy with his invitations, can't he?\n\nI've had one of my servants write up a few slightly-counterfeit invitations to hand out. Maybe you could help me get them distributed? There's always plenty of tough-looking characters hanging out in front of the auction house in the Trade District...", completion = "You placed the sign? Good. Now we just wait for the newbies to show up.\n\nI like you, {name}. You're like me: willing to |cFF0000FFcommit a crime|r or two in the name of self-entertainment.", objectives = "Use the Bizmo's Brawlpub Sign in Stormwind's Trade District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55019] = { id = 55019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evidence Packet: Grant Lazarby", description = "Good work. I never expected Lazarby to be so... self-incriminating.\n\nYou may bring the packet to Commander. I'm going to go buy some expensive snacks at the VIP bar.", completion = "Hmm... I wouldn't be surprised if he killed the quartermaster just for his own entertainment.\n\nFor now, we can bring him in on counterfeiting charges, and get more details in court. Good work.", objectives = "Bring the Evidence Packet to Commander Daalo.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55020] = { id = 55020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brawlpub Trial", description = "I've issued three warrants. Jussho, Saralara, and Anne are apprehending the suspects as we speak.\n\nIt's time to go to court.\n\nYou may be called on to testify. Just answer as honestly as you can, and let the wheels of justice do the rest.", completion = "I really think things were going well there... up to the point where it didn't.\n\nLuckily for us, we've got a new lead. Listen up, {name} - your job isn't done yet.", objectives = "Reach a verdict in the Brawlpub Trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55021] = { id = 55021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Clue from Area 52", description = "We've received a letter from Area 52, the goblin outpost in Netherstorm. The author claims to know details about what they call \"the situation in the Brawlpub\".\n\nThey don't say more than that.\n\nI'm tied to my paperwork here. Go check out this lead and see if anything turns up.", completion = "These mysterious impostors may have gotten the better of me, and they may have gotten away with murder, but little do they know... I hold the trump card!", objectives = "Investigate Area 52 in Netherstorm for a sign of the letter's writer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55022] = { id = 55022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solving the Mystery", description = "<Bizmo produces a challenge card from his pocket.>\n\nI grabbed this challenge card from my attackers while we were fighting each other! I'm sure that you can use it to challenge my attacker to some sort of ultimate showdown!", completion = "I was there, {name}. I saw your fight.\n\nWe've had our suspicions about this \"Watcher\" character since the incident in Quel'Danas. It seems the rumors are true. They are watching us.\n\nI'll relay the information to the correct authorities. Meanwhile, Bizmo and I have arranged for a suitable reward for you. I hope you find it to your liking.", objectives = "Bring the Mysterious Challenge Card to Bizmo's Brawlpub to confront Bizmo's captor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55023] = { id = 55023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bizmo's Brawlpub Awaits!", description = "Tired of standing around in the boring old Trade District? Come on over to Bizmo's Brawlpub, and fight for the amusement of others!\n\nYou might win, or you might get killed, but either way, you're going to have a great time.\n\nGrab an invitation and bring it to Han Heavypaw, near the front door. The Brawlpub awaits!", completion = "<Han inspects the invitation intently.>\n\nHmph. Looks good enough to me. Come on in.", objectives = "Bring an invitation to Bizmo's Brawlpub.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55028] = { id = 55028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Scrap Work...", description = "{name}, I'm glad you stopped by.\n\nThe Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap.\n\nYou'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open!\n\n<Layla makes finger guns and explosion sounds>\n\nUp for some treasure huntin'?", progress = "Did you find the schematic?", completion = "Great, let me see what it says!", objectives = "Use the Coiled Current Culler on dead V-300 SENTRIES at the Abandoned Junkheap, then use it to collect the Ub3r-Spanner schematic from the Reinforced Schematic Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55030] = { id = 55030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Scrap Trap", description = "<This blueprint details how to build what appears to be some sort of land mine using little more than scrap metal.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste.", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55031] = { id = 55031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Scrap Work...", description = "{name}, I'm glad you stopped by.\n\nThe Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap.\n\nYou'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open!\n\n<Shuga makes finger guns and explosion sounds>\n\nUp for some treasure huntin'?", progress = "Did you find the schematic?", completion = "Great, let me see what it says!", objectives = "Use the Coiled Current Culler on dead V-300 SENTRIES at the Abandoned Junkheap, then use it to collect the Ub3r-Spanner schematic from the Reinforced Schematic Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55032] = { id = 55032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unchained Resistance", description = "The naga have enslaved a tribe of makrura and sent them to labor as mindless thralls.\n\nThe naga forces may be more in number, but the makrura have an innate advantage in both size and strength.\n\nIf we break the makrura from their chains, they will surely overwhelm their naga overseers and put a dent in Queen Azshara's plans.", progress = "The makrura will make short work of their former masters.", completion = "The naga will be no match for the makrura prisoners that we have freed.", objectives = "Free 6 Makrura Slaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55033] = { id = 55033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes to Ashvane", description = "This place is just crawling with Ashvane loyalists, {name}.\n\nHow about we do the Kul Tirans a favor and get rid of some of them.\n\n<Kelsey grins.>\n\nI got a head start on the way here, but there's plenty to go around!", completion = "Nice work. They'll have a harder time recruiting now.", objectives = "Slay Ashvane Loyalists in Freehold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55034] = { id = 55034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under False Colors", description = "If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. You'll need to have your men take the ship to Chandlery Wharf, where they can disguise it as a pirate's bounty.\n\nYour task will be to ensure that Sylvanas' forces find the ship there.\n\nYou must report to Nathanos that you spotted a stolen Forsaken vessel in that area.  You have no connection to Derek Proudmoore, so it should raise no suspicions.", completion = "So not only did Baine and Zelling conspire to free Derek Proudmoore, but they turned him over to our enemy? \n\nThey have signed their own death warrants.\n\nYour assistance in this matter is appreciated, {name}. The Dark Lady will know of your loyalty.", objectives = "Start the mission \"Casting the Bait\" then report to Nathanos Blightcaller aboard the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55036] = { id = 55036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Terrible Place", description = "You may have noticed all the disturbances happening around Azeroth. The Old God is rising, and its bad news for all of us.\n\nOn occasion, one of these Pillars of Endless Truth will appear. Wonderful name don't you think? I have a knack for naming things. \n\nWhere was I? Oh yes, right, these Pillars grant one access to the very mind of the Old God himself. They will show you a hint of what might yet come, what this world will look like should we fail to defeat him.\n\nAre you willing to see for yourself?", objectives = "Complete a Vision of N'Zoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55039] = { id = 55039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master Shipwright", description = "Now I am starting to remember...\n\nDorian Atwater was a very secretive builder. Their slips were famously warded against prying eyes until the vessel was complete. It made something of a stir any time one of their works was revealed.\n\nLast I heard, they retired in Stormsong Valley. I am not certain how reliable that information is.\n\nHm. We should head to Brennadam. It is a crossroads of sorts. If anyone knows where to find our shipwright, they will be there.", progress = "You've got that letter? I have a feeling we'll be needing it before long.", completion = "Right. Let's get started.", objectives = "Acquire the Letter from the Lord Admiral and meet Cyrus Crestfall in Brennadam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55040] = { id = 55040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking Inside", description = "This vault screams of ancient gnomish tech! I believe this could be the key that leads us to King Mechagon!\n\nI can't risk putting myself in danger though, so you will lead the way into the vault. \n\nWell, what are we waiting for? Let's see what's inside!", completion = "This is such a great moment in gnomish history. Your help here will be noted in the historical journals.", objectives = "Enter the vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55043] = { id = 55043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Tales and Distant Sails", description = "I have an idea where to start, but it couldn't hurt to ask the locals. \n\nI hope it goes without saying that you shouldn't believe everything you hear, {name}. My people are very fond of embellishing the truth.\n\nI will meet you in The Golden Flagon when you've had a chance to ask around.", progress = "Did you learn anything useful?", completion = "<He studies a map of Stormsong Valley.>\n\nWhat's the word, {name}?", objectives = "Ask for information about the shipwright in Brennadam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55044] = { id = 55044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Shoot the Messenger", description = "While he was the gladiator known as Lo'Gosh, King Varian fought beside Valeera Sanguinar. He trusted her and that allowed SI:7 to have a... cordial relationship with her. Valeera's loyalty has carried on to King Anduin.\n\nDuring the fight with the Legion, I came to know her as a capable if... independent operative. She can go where even some of my agents cannot.\n\nWe should listen to whatever message she brings. I imagine the source will be interesting.", progress = "This is... surprising news.", completion = "Anduin is very trusting. Varian was much less so and chose his friends and allies carefully. But Master Shaw has a finely tuned sense of paranoia, shall we say. If he believes Valeera speaks the truth about Baine, then I am inclined to follow his lead.", objectives = "Listen to Valeera's message.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55045] = { id = 55045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Brother's Keeper", description = "While I trust Valeera believes she is not leading us into a trap, I do not trust this isn't a Horde manipulation.\n\n{name}, I want you to come with me. I will meet with Baine, but I will not do so alone.", progress = "This is... surprising news.", completion = "He returned her brother?\n\nThat... took guts on his part. I wonder at the repercussions for both him and for us here.", objectives = "Sail with Jaina to meet Baine off the coast of Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55047] = { id = 55047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing Warfang Hold", description = "The Dark Lady has important work for you, {name}.\n\nPreparations are beginning for a meeting of the Horde's leadership at Warfang Hold. I trust I don't need to emphasize that security is of the highest import for this gathering.\n\nThe goblin, Gallywix, has sent his underlings to make sure the area is swept of any... unwanted guests. I need you to make sure they succeed in their task.", completion = "So Nathanos thinks we don't have the situation under control? Well, he's right. \n\nJust don't tell him that. Smug jerk would never let me hear the end of it.", objectives = "Meet with Boss Mida at Warfang Hold in Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55048] = { id = 55048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spy Games", description = "The Alliance must've got wind of this meeting and they've sent SI:7 spies to try to listen in.\n\nThe problem is, they're using some kind of gnomish tech to sneak past our detectors. One of our techs was able to put together something that should be able to neutralize whatever they're using, but the range is short. \n\nI'll need you to take it out into the field and look for evidence of SI:7 activity. Just mash the button on that thing when you think they're close, and it should zap 'em back into view.", completion = "Looks like goblin tech wins again!\n\nSeriously though, thanks for saving my hide.", objectives = "Use the Electronic Mayhem Projector to reveal and kill 10 SI:7 spies in the Clearcut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55049] = { id = 55049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Communication Breakdown", description = "It looks like the stealth generators aren't the only tech that SI:7 is bringing into the field. Our scouts have reported what look like listening devices set up at key points around Warfang. \n\nObviously, these things have to go, but the goons haven't been able to get close to them on account of the hidden spies. \n\nWhile you're out there, make sure to trash 'em.", completion = "Looks like I owe you another one, pal.\n\nI'll have Kazit add it to the books.", objectives = "Destroy 3 SI:7 Listening Devices near Warfang Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55050] = { id = 55050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tickets, Please?", description = "There's another problem we could use your help with, {class}. \n\nGallywix knew this meeting was going to be a big deal, so naturally he decided to sell tickets.  The thing is, I've done a headcount here, and we've got a lot more people here than tickets sold, so some of these spectators are trying to pull a fast one.\n\nMost of our muscle is out in the Clearcut getting killed by spies, so we could use the help. Care to make an honest wage?", progress = "The nerve of these people!", completion = "<Kazit makes some tallies in his notebook.>\n\nYeah, that's lookin' about right. Here's your pay.\n\nHey, don't give me that look. I said an honest wage, not a good one!", objectives = "Eject 5 ticketless Visiting Spectators from Warfang Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55051] = { id = 55051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Display of Power", description = "It looks like all the big players are here. This thing's gonna be starting any moment now.\n\nYou'll probably want to get a good seat.", completion = "This is a troublesome turn of events.\n\nI'm afraid the Banshee Queen may have set in motion a ruinous path for the Horde. \n\nKeep your eyes and ears open, {name}. The day is not yet done.", objectives = "Speak to Nathanos Blightcaller to witness the meeting of leaders in Warfang Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55052] = { id = 55052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing Warfang Hold", description = "{name}, the Dark Lady has need of your services once more.\n\nThe traitor, Baine, is being brought before the leaders of the Horde at Warfang Hold. Preparations are underway as we speak to secure the area.\n\nThe efforts are headed up by Gallywix's minions, who I wouldn't trust to secure a kennel. You will need to go to Warfang Hold and make sure the area is locked down.\n\nWe are counting on you, {name}.", completion = "So Nathanos thinks we don't have the situation under control? Well, he's right. \n\nJust don't tell him that. Smug jerk would never let me hear the end of it.", objectives = "Meet with Boss Mida at Warfang Hold in Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55053] = { id = 55053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Way Home", description = "We can harness the power within this place to open a portal home.\n\nI will require your assistance. Isn't this fun? You get to be my assistant!\n\nAh, yes. Just come with me and all you have to do is wave that Heart of Azeroth of yours around. I'll handle the rest.", completion = "A job well done!", objectives = "Help Oculeth open a portal to Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55054] = { id = 55054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upheaval", description = "We're surrounded by the dead, dying, and other detritus.\n\nFeels like war, does it not?\n\nOculeth and others have gone ahead to see to the soldiers.\n\nPerhaps you ought to see to them as well?", completion = "Not to worry, {name}. It's not as if I'd magic you into the middle of the ocean without notice! Well, I suppose that is where we are, is it not?", objectives = "Speak with Chief Telemancer Oculeth at the top of the waterfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55055] = { id = 55055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Build A Bigger Fish Trap", description = "With those minnows and some spare parts, you should be able to build a Hundred-Fathom Lure.\n\nVisit Pascal-K1N6 in Rustbolt and build one.\n\nThen come back here, and we'll catch a huge fish!", progress = "Get to it, we have a fish to catch!", completion = "Now, let's catch us a fish!", objectives = "Build the Hundred-Fathom lure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
