quests[55087] = { id = 55087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gathering Storm", description = "While I deal with the naga incursions, Lady Proudmoore is going to take on handling the Horde in Stormsong Valley and figuring out what happened to our spies there.\n\nYou'll find her near Proudmoore Keep.", completion = "It appears the Horde activity in Stormsong Valley is more serious than we originally thought.", objectives = "Report to Jaina Proudmoore near Proudmoore Keep in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55088] = { id = 55088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in the Field", description = "When Shaw and I got here we discovered most of our operatives were dead. Most, but not all. \n\nGo into the field and get any of our operatives out of there. They might have more intel on what the Horde are planning here in Warfang Hold.", completion = "Our people stumbled onto something really big out here!", objectives = "Assist injured spies in Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55089] = { id = 55089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaw's Shank Redemption", description = "Hmm. Shaw said he'd check in when we got communications back but he hasn't. He's probably run into the same trouble the rest of our spies did.\n\nI'll stay here and guard the listening post. You find Shaw. He was headed for the cliff above Warfang Hold near the top of the waterfall. The peons called that area \"The Screaming Pit\" for some reason. I bet it's a real pleasant place.\n\nStab whatever he's fighting for me, okay?", progress = "Just in time, {name}.", completion = "They've increased security here beyond anything we expected, and with good reason.", objectives = "Find Mathias Shaw in The Screaming Pit above Warfang Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55090] = { id = 55090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering of Foes", description = "Before I was distracted, I was able to find out more about this Horde gathering. Sylvanas has summoned the leaders of the Horde and its allies. For what purpose, I cannot say.\n\nWe aren't in a position to strike her down--she is too well-protected. But perhaps we can learn something that will prove useful in the ongoing war.\n\nKeep your head low and take a look. I'll keep an eye out for more guards.", completion = "I cannot help but pity Baine. Honor such as his has lost its value in the Horde.\n\nSylvanas has made a bold move. We'll go after her, but she's cunning. We need to push back the naga and gather our forces for a final strike.", objectives = "Witness the Horde gathering.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55092] = { id = 55092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disruption of Power", description = "The naga tap into the power within nearby ley lines and have found a way to harness it.\n\nDestroy their devices before they can put that power to use against us.", completion = "Hopefully we will never find out what they were drawing in such power for.", objectives = "Destroy 5 Ley Line Accumulators in Spears of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55094] = { id = 55094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stay Low, Stay Fast!", description = "It's a straight shot home. We just need to be careful.\n\nNeri's rule of survival number six: always be prepared!\n\nLet's go!", completion = "Finally, some small relief. But we must not rest easy; Azshara surely has more in store for us than she lets on.", objectives = "Follow Neri Sharpfin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55095] = { id = 55095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upheaval", completion = "Finally, some good news. Our champion awakens from the chaos.", objectives = "Speak with Lady Jaina Proudmoore above the waterfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55096] = { id = 55096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send My Father a Message", description = "My people are once again safe... for now.\n\nKing Mechagon won't stop sending his armies at us as long as he does not fear us.\n\nWe must send him a message.\n\nClimb to the top of the ramparts, and hack one of my father's projectors to proudly shine the banner of the Rustbolt Resistance big enough for the whole island to see.\n\nI'm sure that'll attract the attention of my father, King Mechagon.", completion = "Rustbolt already looks improved, doesn't it?\n\nIt's not the first time we've had to rebuild it, and it won't be the last.", objectives = "Hack a projector to display the Rustbolt Resistance emblem and defend it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55101] = { id = 55101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junkyard Tinkering and You", description = "Behold, the fabled Pascal Workshop of Rustbolt -- MY workshop!\n\nCountless inventions have sprung forth into existence on this very spot, including my very finest invention, Pascal-K1N6!\n\nPascal-K1N6 can craft anything... as long as you have the blueprints for it.\n\nAnd since I have you to thank for the K1N6's safe return to Rustbolt, would you like to learn how to access his blueprints database?", progress = "Remember, you can collect Spare Parts from almost anything on Mechagon.", completion = "Pascal-K1N6 is a marvel of junkyard tinkering! A wonder of the modern age!\n\nDid I mention that I invented him myself? Of course I did.", objectives = "Use Pascal-K1N6 to craft a Scrap Grenade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55103] = { id = 55103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ideas Can Come from Anywhere", description = "I didn't notice the tinkerer's spark in you when we first met.\n\nBut look at all of the blueprints you've recovered and uploaded to Pascal-K1N6's database.\n\nI was wrong. And happily so, my budding junkyard tinkering apprentice!\n\nBut this is a dangerous moment in your creative development.\n\nYou must avoid complacency!\n\nTake time off to find new ideas. Speak with builders that inspire you, reverse-engineer bots on the island, and be open to new ideas - no matter where they come from!", completion = "I see it! The spark of new ideas in your eyes...\n\nYou've returned from your travels fresh and ready to brainstorm some blueprints!\n\nI have too. Let's discuss.", objectives = "Find people and things to inspire 1 new ideas in Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55111] = { id = 55111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Study: Zanj'ir Naga", description = "<Scrawled upon the magical scroll are Maedin's incomplete notes on the Zanj'ir naga.>", objectives = "Use Maedin's Scroll to collect data from various creatures within Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55116] = { id = 55116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting a Clue", description = "I'm betting that one page of jibberish is a coded message. We can send it back to Stormwind to be cracked by our codebreakers or we could break some heads and find the cipher here.\n\nI'm thinking we'll just save some time and do that.\n\nThe guy in charge here probably has what we're looking for. Why don't you take him out and see if you can't find it. Even if you don't, without a leader the loyalists won't be much trouble. It's a win-win!\n\nWell, for us I guess.", progress = "Did you find a cipher? Or some kind of decoding gadget?", completion = "A decoder ring? Can't go wrong with the classics I guess.\n\n<Kelsey uses the ring to decode the message.>\n\nThis is from Ashvane alright. The date on here is pretty old though. The \"patron\" she mentions is something they're gonna want to hear about back in Boralus.", objectives = "Slay Haughton Francis and recover his cipher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55117] = { id = 55117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Correspondence Conundrum", description = "I think Ashvane has been in contact with her loyalists, but I don't know what their orders are.\n\nGo into their camp and see if you can't read their mail. We might find something that leads back to where Lady Ashvane is hiding or what their next move is going to be.", completion = "A recipe, a personal letter.... a grocery list? Oh! Yeah, this is a coded communication. Hmmm\n\n<Kelsey rubs her chin and idly flips one of her knives as she thinks>\n\nI'm betting whoever is in charge here has the cipher. Why don't you go pay them a visit and get it for us.", objectives = "Discover information about Lady Ashvane's plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55118] = { id = 55118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loose Ends", description = "Our campaign against the Horde is going strong, but there are some loose threads to take care of.\n\nLady Ashvane was broken out of Tol Dagor - by the Horde. We don't know where she's gone or what she is planning. I sent Kelsey out to track down some Ashvane Loyalists to get answers. She found them and has requested backup.\n\nShe's waiting for you in Freehold.", completion = "I found a whole nest of these guys!\n\nYou ready to help me take 'em out?", objectives = "Meet Kelsey Steelspark in Freehold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55119] = { id = 55119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reporting In!", description = "Well it looks like Ashvane's been out of contact for some time but this 'Patron' thing could be a problem.\n\nYou did excellent work today, {name}. Those Loyalists aren't going to be thinking about causing trouble for awhile, heh.\n\nI'll make my way back. You take the letter to the High Commander.", progress = "Did you find anything on Ashvane?", completion = "<Wyrmbane gestures to the letter>\n\nIf this was Ashvane's last communication, perhaps her meeting with this mysterious \"patron\" of hers did not go as she planned.\n\nWe'll keep an eye on this. In the meantime, perhaps you'd better speak with our... guest.", objectives = "Report to Halford Wyrmbane in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55121] = { id = 55121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Laboratory of Mardivas", description = "<Several pages are devoted to notes on an experiment, a hastily written journal entry follows.>\n\nAt last, my research into the base elements has begun to bear fruit!\n\nWith careful application of the right base reagents and some arcane power I've managed to combine the essence of the elements in such a way as to create life!\n\nFurther investigation will be needed to determine what the various mixes of the elements will yield.\n\n<The writing ends here.>", progress = "<The remaining pages are filled with gibberish and strange doodles.>", completion = "<The magic of the system appears to have been drained. Perhaps after some time has passed it can be used again.>", objectives = "Activate the Elemental Essence Amalgamator in Mardivas's Laboratory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55122] = { id = 55122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murloc Mania", description = "I'm glad you made it out in one piece. \n\nJudging by the nearby shipwrecks, I think it's safe to say the missing expedition ran aground here, too.\n\nWe can't move until we've got the remaining survivors back on their feet. \n\nUnfortunately, our remaining supplies have been stolen by murlocs! \n\nI need you to recover enough first aid supplies for the wounded. \n\nThen we can begin searching for the missing expedition.", progress = "Did you recover the first aid kits? Don't take the murlocs lightly.", completion = "Excellent work. Let's get the survivors back on their feet.", objectives = "Recover 6 First Aid Kits from Murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55123] = { id = 55123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Season" }
quests[55124] = { id = 55124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righting Wrongs", description = "Champion! I come with an urgent request from Baine Bloodhoof. He asks that you meet him at Plunder Harbor to help him with a... sensitive situation.\n\nYou must tell no one of this request, {class}. \n\nAncestors watch over you.", completion = "You're here.\n\nGood, now we can proceed.", objectives = "Meet with Baine Bloodhoof at Plunder Harbor in Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55125] = { id = 55125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Season" }
